$$\begin{align*}
\mathbf{v}-2\mathbf{u}&=\begin{pmatrix}2\\3\end{pmatrix}-2\begin{pmatrix}5\\-1\end{pmatrix}\\
&=\begin{pmatrix}2-10\\3+2\end{pmatrix}\\
&=\begin{pmatrix}-8\\5\end{pmatrix}
\end{align*}$$

$$\begin{align*}
|\mathbf{v}|&=\sqrt{2^2+3^2}\\
&=\sqrt{13}
\end{align*}$$

$$\begin{align*}
\hat{\mathbf{v}}&=\frac{\mathbf{v}}{|\mathbf{v}|}\\
&=\frac{1}{\sqrt{13}}\begin{pmatrix}2\\3\end{pmatrix}\\
&=\frac{2}{\sqrt{13}}\mathbf{i}+\frac{3}{\sqrt{13}}\mathbf{j}
\end{align*}$$

$$\begin{align*}
\operatorname{proj}_{\mathbf{v}}\mathbf{u}&=\frac{\mathbf{u}\cdot\mathbf{v}}{|\mathbf{v}|^2}\mathbf{v}\\
&=\frac{7}{13}\begin{pmatrix}2\\3\end{pmatrix}\\
&=\frac{14}{13}\mathbf{i}+\frac{21}{13}\mathbf{j}
\end{align*}$$

